package org.kanger.storage.dumb2;
import java.util.*;import java.nio.file.*;import org.kanger.*;import org.kanger.storage.dumb2.ContextNativeCandidateLeaseMatrix.Fixture;
public final class ContextThreeVariablePublicationRunner {
 static int checks;static final String RULE="!@u @v @w p(u)&&q(v)&&r(w)->s(v);";static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}static Set<String> primary(Fixture f)throws Exception{return ContextNativeCommitGuardMatrix.primary(f);}static ContextSignedModelRequest request(String s){return new ContextSignedModelRequest(s,Collections.emptyMap());}
 public static void main(String[] args){try{Path d=Files.createTempDirectory("three-variable-publication-");System.setProperty("user.home",d.toString());
  try(Fixture f=new Fixture(d,"Three")){String[] out=ContextAutomaticModelMatrix.console(f.mind,"ctx candidate model write \""+RULE+"\"\n");require(out[0].contains("MODEL WRITE: PUBLISHED")&&out[1].trim().isEmpty(),"actual Console first three-variable model publication");}
  try(Fixture f=new Fixture(d,"Three")){require(primary(f).equals(Collections.singleton(RULE)),"durable ONLY whole three-variable original");String[] out=ContextAutomaticModelMatrix.console(f.mind,"!p(1);\n!q(2);\n!r(3);\n?s(2);\n");require(out[0].contains("Result: TRUE")&&out[1].trim().isEmpty(),"actual Console distinct u=1,v=2,w=3 follows middle-variable head");}
  try(Fixture f=new Fixture(d,"Three")){require(primary(f).size()==4&&primary(f).contains(RULE)&&!primary(f).contains("!s(2);"),"no derived/model fact persisted as new original");require(Boolean.TRUE.equals(f.mind.query("?s(2);",null,false)),"cold reopen native three-variable chain true");}
  ContextNativeCandidateLeaseMatrix.create(d,"Facts","!p(1);!q(2);!r(3);");ContextNativeCandidateLeaseMatrix.create(d,"Negative","!~s(2);");try(Fixture f=new Fixture(d,"Refuted")){f.db.connectContext("Facts");f.db.connectContext("Negative");long before=f.db.getRevision();ContextSignedModelPublication no=f.db.publishSignedModelCandidate(f.mind,request(RULE));require(no.status==ContextSignedModelPublication.Status.REFUTED&&no.evidence!=null,"three-variable actual conflict refuted");require(no.evidence.getOppositions().stream().anyMatch(o->o.sources.size()==5),"exact five original Sources");no.evidence.check(64000000,64);require(primary(f).isEmpty()&&before==f.db.getRevision(),"atomic refusal leaves X empty/revision unchanged");}
  try(Fixture f=new Fixture(d,"Bounded")){long before=f.db.getRevision();ContextSignedModelPublication no=f.db.publishSignedModelCandidate(f.mind,new ContextSignedModelRequest(RULE,Collections.singletonMap("audit",1)));require(no.status==ContextSignedModelPublication.Status.INCOMPLETE,"tiny three-variable audit budget no acceptance/conflict proof");require(primary(f).isEmpty()&&before==f.db.getRevision(),"bounded failure atomic");}
  try(Fixture f=new Fixture(d,"Four")){long before=f.db.getRevision();ContextSignedModelPublication no=f.db.publishSignedModelCandidate(f.mind,request("!@u @v @w @z p(u)&&q(v)&&r(w)&&s(z)->t(u);"));require(no.status==ContextSignedModelPublication.Status.INCOMPLETE,"native binding still rejects four-variable rule");require(primary(f).isEmpty()&&before==f.db.getRevision(),"four-variable refusal leaves no partial row");}
  System.out.println("THREE_VARIABLE_PUBLICATION actualConsole=true middleHeadDistinctValues=true durableOriginalsOnly=true fiveSourceAtomicRefusal=true workAndBindingBounds=true");System.out.println("CONTEXT_THREE_VARIABLE_PUBLICATION_PASS checks="+checks);System.exit(0);
 }catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
